import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.D7EuCHIT.js";const _=JSON.parse('{"title":"实现播放提供者","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/playback.md","filePath":"plugins/playback.md","lastUpdated":1791828780000}'),o={name:"plugins/playback.md"};function i(n,e,s,p,l,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="实现播放提供者" tabindex="-1">实现播放提供者 <a class="header-anchor" href="#实现播放提供者" aria-label="Permalink to &quot;实现播放提供者&quot;">​</a></h1><p>这是难度最高的扩展边界。官方 FFmpeg 插件可作完整参考；mock_provider 只模拟状态，没有音频，不能当作播放器发布。</p><p>替换 <code>playback</code> 服务并发布 <code>LYRA_INTERFACE_PLAYBACK_PROVIDER</code>。不要链接宿主隐藏 C++ 符号，不增加第二套 App 播放状态；公开交互使用 C ABI。</p><h2 id="必要回调" tabindex="-1">必要回调 <a class="header-anchor" href="#必要回调" aria-label="Permalink to &quot;必要回调&quot;">​</a></h2><table tabindex="0"><thead><tr><th>回调</th><th>行为</th></tr></thead><tbody><tr><td>snapshot</td><td>输出按值快照，支持并发安全读取</td></tr><tr><td>command</td><td>接受 OPEN/STOP/PAUSE/RESUME/SEEK/PRIME/CLEAR_PRIME/REAP/REMEMBER</td></tr><tr><td>listener</td><td>注册事件回调，不保留进度快照指针</td></tr><tr><td>quiesce</td><td>所有线程/回调退出后返回 1</td></tr><tr><td>lyrics</td><td>按 generation/track 读取有界嵌入歌词</td></tr></tbody></table><p>OPEN 被接受后接管 fd。拒绝保持未消费；所有后续关闭只做一次。清理顺序不能让线程读取已关闭 fd 或已释放 decoder。</p><h2 id="主时钟" tabindex="-1">主时钟 <a class="header-anchor" href="#主时钟" aria-label="Permalink to &quot;主时钟&quot;">​</a></h2><p>position_us 必须由实际输出位置推导，包含解码起点、seek 时间重定位、采样帧、暂停冻结和系统输出时间戳的处理。不是解码到哪就报告到哪。UI 通过本帧统一快照消费位置。</p><p>seek 请求时先标 seeking，落地时改变 origin/revision、landed_seek，并清理旧 PCM 和特征。连续 seek 以 serial 区分，不能让先发但晚完成的结果覆盖新目标。generation 隔离换歌与提供者更换；音频特征使用同一输出时间轴和 feature_epoch。</p><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>0 EOF、1 播放失败、2 实际音频进度、3 seek 失败。事件带 generation，进度可带只在调用期间借用的值快照。进度记忆使用实际输出位置，不能保存 UI 拖动预览。</p><p>不要在 AAudio 实时回调执行插件注册、网络、绘制或磁盘写入。恢复缓冲、解码、特征分析和保存分别有明确线程与缓冲所有权。</p><h2 id="切换" tabindex="-1">切换 <a class="header-anchor" href="#切换" aria-label="Permalink to &quot;切换&quot;">​</a></h2><p>宿主记录实际位置和暂停状态，阻止新读调用，等待正在读的调用，STOP，再等待 quiesce。安全退出后解除旧 listener、增加 generation 并绑定新提供者。拒绝退出会保留旧库。</p><p>手机测试锁屏、长后台、焦点打断、耳机/蓝牙变更、暂停/恢复、连续 seek、连续换歌与卸载。静音生命周期测试只证明控制与资源边界，不证明音质或输出延迟。</p><p><a href="https://github.com/xu-yuanhao/LyraPlayer-plugins/tree/main/plugins/ffmpeg" target="_blank" rel="noreferrer">官方插件源码</a>。格式能力取决于系统解码器或插件，不承诺默认设备原生支持所有格式。</p>',16)])])}const u=t(o,[["render",i]]);export{_ as __pageData,u as default};
